-- Generated by officehours - do not edit by hand.
PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;

DROP VIEW IF EXISTS class_schedule;
DROP VIEW IF EXISTS office_hours_schedule;
DROP TABLE IF EXISTS office_hours;
DROP TABLE IF EXISTS teaches;
DROP TABLE IF EXISTS course_days;
DROP TABLE IF EXISTS courses;
DROP TABLE IF EXISTS professors;

CREATE TABLE professors (
    id          INTEGER PRIMARY KEY,
    name        TEXT NOT NULL UNIQUE,
    department  TEXT,
    email       TEXT,
    office      TEXT,
    office_hours_source TEXT NOT NULL CHECK (office_hours_source IN ('generated', 'provided'))
);

CREATE TABLE courses (
    id          INTEGER PRIMARY KEY,
    code        TEXT NOT NULL,
    title       TEXT,
    section     TEXT,
    lecturer    TEXT,           -- as written in the syllabus
    room        TEXT,
    start_time  TEXT,           -- 'HH:MM', NULL for online / TBA
    end_time    TEXT
);

CREATE TABLE course_days (
    course_id   INTEGER NOT NULL REFERENCES courses(id),
    day         TEXT NOT NULL,
    day_number  INTEGER NOT NULL,   -- 1 = Monday ... 7 = Sunday
    PRIMARY KEY (course_id, day)
);

CREATE TABLE teaches (
    professor_id INTEGER NOT NULL REFERENCES professors(id),
    course_id    INTEGER NOT NULL REFERENCES courses(id),
    PRIMARY KEY (professor_id, course_id)
);

CREATE TABLE office_hours (
    id           INTEGER PRIMARY KEY,
    professor_id INTEGER NOT NULL REFERENCES professors(id),
    day          TEXT NOT NULL,
    day_number   INTEGER NOT NULL,
    start_time   TEXT NOT NULL,
    end_time     TEXT NOT NULL,
    course_code  TEXT
);

-- Every class meeting, one row per professor, course and day.
CREATE VIEW class_schedule AS
    SELECT p.name AS professor, c.code, c.title, c.section, d.day, d.day_number,
           c.start_time, c.end_time, c.room
    FROM teaches t
    JOIN professors p ON p.id = t.professor_id
    JOIN courses c ON c.id = t.course_id
    JOIN course_days d ON d.course_id = c.id;

-- Every office-hour block with the professor's name.
CREATE VIEW office_hours_schedule AS
    SELECT p.name AS professor, o.day, o.day_number, o.start_time, o.end_time,
           o.course_code, p.office, p.office_hours_source AS source
    FROM office_hours o
    JOIN professors p ON p.id = o.professor_id;

